#!/usr/bin/env bash
# Daily publish. Run after grade.py, from inside the site repo.
#
# Only data/status.json changes day to day, so the HTML is never
# rebuilt and nothing has to be regenerated by hand. If site_data.py
# fails, the old status.json is left in place and nothing is pushed --
# a stale number is better than a blank panel or a corrupt file.
set -euo pipefail
cd "$(dirname "$0")"

TMP=$(mktemp)
if ! python3 ~/Downloads/site_data.py --json > "$TMP"; then
  echo "site_data.py failed — leaving the published status alone"; rm -f "$TMP"; exit 1
fi
python3 -c "import json,sys; json.load(open(sys.argv[1]))" "$TMP" || {
  echo "site_data.py produced invalid JSON — not publishing"; rm -f "$TMP"; exit 1; }
mv "$TMP" data/status.json

if git diff --quiet; then
  echo "nothing changed today"; exit 0
fi
git add -A
git commit -q -m "board update $(date +%Y-%m-%d)"
git push -q
echo "published $(date +%Y-%m-%d)"
